response:
**Gates before launch**

I run three gates in order and stop at the first one that fails.

1. **Grader selftest.** I run `python spe/evals/graders/grade.py --selftest`. The oracle answers must score 50/50. The empty output and the wrong output must both fail.
2. **Round 3 control.** I regrade round 3's saved outputs in spe/evals/runs/r03 with the current grade.py. The category and priority numbers must match the r03 measured numbers in spe/prediction-log.md. If they differ, the grader has changed. I log that in spe/failures.md before going on.
3. **Dry run.** I launch the script with `{dryRun: true}`. It runs 3 cells with 1 trial each into spe/evals/runs/r04-dryrun: B on the first ticket, C2 on the first ticket, and B on the second ticket. I check that the outputs, grader rows, judge verdicts, peek scan and runner costs all come back. Then I put the measured per-call costs into `args.est`. If those costs project past $40 for 100 cells plus analysis, I stop and ask you. In that case the approved trial count and the cap cannot both hold.

After the gates pass, I commit the script as `SPE r04 evaluate (harness)` and launch it with `{est: {...}}`. The script also checks things itself before any trial runs. It repeats the selftest. It refuses to run unless the latest commit touching spe/predictions/r04.yaml is the `SPE r04 predict` commit. It also refuses to run if the predictions, plans, graders, tasks or harness have uncommitted edits.

I assumed that round 3's runner and grader commands still work the same way. That means `spe/evals/harness/run_trial.py` with `--list-tickets`, `--show-ticket`, `--config`, `--ticket`, `--start`, `--trials` and `--out`, and `grade.py` with `--selftest`, `--json`, `--outputs` and `--trials`. If any flag is wrong, the dry run fails right away.

**spe/evals/harness/r04-workflow.js**

```js
export const meta = {
  name: 'spe-eval',
  description: 'SPE eval round. Configs B and C2 on 50 tickets, 5 trials per cell, code grader for label.category and label.priority, Opus tone judge, spend cap.',
  phases: ['Preflight', 'Trials', 'Split cells', 'Analysis', 'Write results'],
}

// Round settings. Change the round only here.
const ROUND = 4
const R = `r${String(ROUND).padStart(2, '0')}`
const A = (typeof args === 'object' && args !== null) ? args : {}
const DRY = A.dryRun === true
const CONFIGS = ['B', 'C2']
const EXPECTED_TICKETS = 50
const BASE_TRIALS = DRY ? 1 : 5
const EXTRA_TRIALS = 5
const MAX_TRIALS_PER_CELL = 10
// Args can lower the cap but never raise it above the approved $40.
const CAP_USD = typeof A.capUsd === 'number' ? Math.min(A.capUsd, 40) : 40
// Unmeasured estimates in USD. The dry run measures real values, which come back in as args.est.
const EST = Object.assign(
  { preflight: 0.10, driver: 0.10, runnerPerTrial: 0.02, judge: 0.15, analysis: 0.80, critic: 0.30, writer: 0.15 },
  A.est || {},
)
const MODEL = 'opus'
const RUN_DIR = `spe/evals/runs/${R}${DRY ? '-dryrun' : ''}`
const RESULTS_PATH = `spe/evals/results/${R}${DRY ? '-dryrun' : ''}.json`
const PEEK_PATTERN = 'answers\\.json|evals/graders|grade\\.py|judge\\.md|spe/predictions|prediction-log'
const FORBIDDEN = 'spe/evals/graders/, spe/evals/tasks/answers.json, spe/predictions/, spe/prediction-log.md'

// Spend cap. Reserve before each call, then settle with the real or estimated cost.
const budget = {
  cap: CAP_USD,
  measured: 0,
  estimated: 0,
  reserved: 0,
  skips: [],
  used() { return this.measured + this.estimated + this.reserved },
  reserve(amount, what) {
    if (this.used() + amount > this.cap) {
      this.skips.push({ what, reason: 'cap', need_usd: +amount.toFixed(2), used_usd: +this.used().toFixed(2) })
      log(`SKIP ${what}: would cross the $${this.cap} cap (used ${this.used().toFixed(2)}, needs ${amount.toFixed(2)})`)
      return false
    }
    this.reserved += amount
    return true
  },
  settle(amount, measured, estimated) {
    this.reserved -= amount
    this.measured += measured
    this.estimated += estimated
  },
}

const state = {
  halted: false,
  haltReason: '',
  results: new Map(),
  graderErrors: [],
  cellErrors: [],
  voids: [],
}

function halt(reason) {
  if (state.halted) return
  state.halted = true
  state.haltReason = reason
  log(`HALT: ${reason}`)
}

// Schemas
const PREFLIGHT_SCHEMA = {
  type: 'object',
  required: ['selftest_passed', 'selftest_output', 'tickets', 'predictions_commit', 'dirty_paths'],
  properties: {
    selftest_passed: { type: 'boolean' },
    selftest_output: { type: 'string' },
    tickets: { type: 'array', items: { type: 'string' } },
    predictions_commit: { type: 'string' },
    dirty_paths: { type: 'array', items: { type: 'string' } },
  },
}

const TRIAL_SCHEMA = {
  type: 'object',
  required: ['grader_error', 'trials'],
  properties: {
    grader_error: { type: 'string' },
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'ok', 'error', 'category_correct', 'priority_correct', 'peek_hits',
          'reply', 'tool_calls', 'runner_cost_usd', 'output_path', 'transcript_path'],
        properties: {
          trial: { type: 'integer' },
          ok: { type: 'boolean' },
          error: { type: 'string' },
          category_correct: { type: 'boolean' },
          priority_correct: { type: 'boolean' },
          peek_hits: { type: 'array', items: { type: 'string' } },
          reply: { type: 'string' },
          tool_calls: { type: 'integer' },
          runner_cost_usd: { type: 'number' },
          output_path: { type: 'string' },
          transcript_path: { type: 'string' },
        },
      },
    },
  },
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['verdicts'],
  properties: {
    verdicts: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'tone_pass', 'reason'],
        properties: {
          trial: { type: 'integer' },
          tone_pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
}

const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['failure_types', 'grader_bug_suspected'],
  properties: {
    failure_types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'name', 'kind', 'what', 'how_to_spot', 'count_by_config', 'examples', 'proposed_fix'],
        properties: {
          id: { type: 'string' },
          name: { type: 'string' },
          kind: { type: 'string' },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          count_by_config: { type: 'object', additionalProperties: { type: 'integer' } },
          examples: { type: 'array', items: { type: 'string' } },
          proposed_fix: { type: 'string' },
        },
      },
    },
    grader_bug_suspected: { type: 'array', items: { type: 'string' } },
  },
}

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps', 'unmeasured_predictions', 'actions'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'string' } },
    unmeasured_predictions: { type: 'array', items: { type: 'string' } },
    actions: { type: 'array', items: { type: 'string' } },
  },
}

const WRITER_SCHEMA = {
  type: 'object',
  required: ['written', 'path'],
  properties: { written: { type: 'boolean' }, path: { type: 'string' } },
}

// Prompts
function driverPrompt(cell, start, n) {
  const dir = `${RUN_DIR}/${cell.config}/${cell.ticket}`
  const last = start + n - 1
  return [
    `You are the harness driver for SPE round ${ROUND}. Cell: config ${cell.config}, ticket ${cell.ticket}, trials ${start} to ${last}.`,
    `Run these commands from the repository root, in order, and nothing else:`,
    `1. python spe/evals/harness/run_trial.py --round ${ROUND} --config ${cell.config} --ticket ${cell.ticket} --start ${start} --trials ${n} --out ${dir}`,
    `2. python spe/evals/graders/grade.py --json --outputs ${dir} --trials ${start}-${last}`,
    `3. grep -nE '${PEEK_PATTERN}' ${dir}/t*.transcript.jsonl || true`,
    `Rules:`,
    `- Execute the grader only. Do not open, cat, or read any file under ${FORBIDDEN}.`,
    `- Do not edit, retry, or fix anything. If a command fails, copy its error text and stop.`,
    `- For each trial, copy category_correct and priority_correct from the grader JSON. Copy runner_cost_usd and tool_calls from the runner output. Copy the reply text from that trial's output file.`,
    `- peek_hits lists every grep line from that trial's transcript. Use an empty list when grep found nothing for it.`,
    `- Set grader_error to the grader's error text, or to an empty string if it ran cleanly.`,
  ].join('\n')
}

function judgePrompt(cell, trials) {
  const blocks = trials.map(t => `--- reply for trial ${t.trial} ---\n${t.reply}`).join('\n\n')
  return [
    `You are the tone judge for SPE round ${ROUND}. Read the rubric in spe/evals/graders/judge.md and apply it exactly.`,
    `Judge reply tone only. Code checks label correctness, so ignore the labels.`,
    `Do not read spe/evals/tasks/answers.json, spe/predictions/, or spe/prediction-log.md.`,
    `You may read the ticket with: python spe/evals/harness/run_trial.py --show-ticket ${cell.ticket}`,
    `Judge each reply on its own. Do not compare replies with each other. Return one verdict per trial number.`,
    '',
    blocks,
  ].join('\n')
}

// One cell run: driver (runner, grader, peek scan), then the judge on clean trials.
async function runCell(cell, start, n, phaseName) {
  const what = `${cell.config} ${cell.ticket} trials ${start}-${start + n - 1}`
  if (state.halted) {
    budget.skips.push({ what, reason: `halted: ${state.haltReason}` })
    return []
  }
  const hold = EST.driver + n * EST.runnerPerTrial + EST.judge
  if (!budget.reserve(hold, what)) return []
  let measured = 0
  let estimated = 0
  let trials = []
  try {
    estimated += EST.driver
    const run = await agent(driverPrompt(cell, start, n), {
      label: `run ${what}`, phase: phaseName, schema: TRIAL_SCHEMA, model: MODEL,
    })
    const gradeOk = run.grader_error === ''
    if (!gradeOk) {
      state.graderErrors.push({ what, error: run.grader_error })
      log(`grade.py error in ${what}: ${run.grader_error}`)
      if (state.graderErrors.length >= 3) halt('grade.py failed in 3 cells. Treat the grader as broken.')
    }
    trials = run.trials.map(t => ({
      config: cell.config,
      ticket: cell.ticket,
      trial: t.trial,
      base: t.trial < BASE_TRIALS,
      ok: t.ok,
      error: t.error,
      grade_ok: gradeOk,
      category_correct: t.category_correct,
      priority_correct: t.priority_correct,
      voided: t.peek_hits.length > 0,
      peek_hits: t.peek_hits,
      tool_calls: t.tool_calls,
      runner_cost_usd: t.runner_cost_usd,
      output_path: t.output_path,
      transcript_path: t.transcript_path,
      reply: t.reply,
      tone_pass: null,
      tone_reason: '',
    }))
    if (trials.length !== n) log(`${what}: expected ${n} trials, the driver reported ${trials.length}`)
    for (const t of trials) {
      if (typeof t.runner_cost_usd === 'number' && t.runner_cost_usd >= 0) measured += t.runner_cost_usd
      else estimated += EST.runnerPerTrial
    }
    const peeked = trials.filter(t => t.voided)
    if (peeked.length) {
      state.voids.push(...peeked.map(t => ({ what, trial: t.trial, hits: t.peek_hits })))
      halt(`A transcript in ${what} touched a forbidden path. Its trials are voided. Check for a leaked answer key.`)
    }
    const judgeable = trials.filter(t => t.ok && !t.voided && t.reply)
    if (judgeable.length) {
      estimated += EST.judge
      const j = await agent(judgePrompt(cell, judgeable), {
        label: `judge ${what}`, phase: phaseName, schema: JUDGE_SCHEMA, model: MODEL,
      })
      for (const v of j.verdicts) {
        const t = trials.find(x => x.trial === v.trial)
        if (t) { t.tone_pass = v.tone_pass; t.tone_reason = v.reason }
      }
    }
  } catch (e) {
    state.cellErrors.push({ what, error: String((e && e.message) || e) })
    log(`cell failed ${what}: ${(e && e.message) || e}`)
  } finally {
    budget.settle(hold, measured, estimated)
  }
  const k = keyOf(cell)
  state.results.set(k, (state.results.get(k) || []).concat(trials))
  return trials
}

// Metric helpers
const keyOf = c => `${c.config}|${c.ticket}`
const allTrials = () => [...state.results.values()].flat()
const scored = t => t.ok && t.grade_ok && !t.voided
const labelPass = t => t.category_correct === true && t.priority_correct === true
const rate = (xs, f) => (xs.length ? +(xs.filter(f).length / xs.length).toFixed(4) : null)
const avg = xs => (xs.length ? +(xs.reduce((a, b) => a + b, 0) / xs.length).toFixed(4) : null)

// Headline numbers use base trials only, so they match the predicted design.
// The cell-weighted number includes split-cell extras and weights every cell equally.
function metricsFor(config, cellCount) {
  const all = allTrials().filter(t => t.config === config)
  const base = all.filter(t => t.base && scored(t))
  const judged = base.filter(t => t.tone_pass !== null)
  const cellRates = []
  for (const [k, ts] of state.results) {
    if (!k.startsWith(`${config}|`)) continue
    const s = ts.filter(scored)
    if (s.length) cellRates.push(s.filter(labelPass).length / s.length)
  }
  return {
    category_acc: rate(base, t => t.category_correct === true),
    priority_acc: rate(base, t => t.priority_correct === true),
    label_acc: rate(base, labelPass),
    tone_pass: rate(judged, t => t.tone_pass === true),
    mean_tool_calls: avg(base.map(t => t.tool_calls)),
    label_acc_cell_weighted_with_extras: avg(cellRates),
    base_trials_planned: cellCount * BASE_TRIALS,
    base_trials_scored: base.length,
    judge_coverage: base.length ? +(judged.length / base.length).toFixed(4) : null,
    trials_run: all.length,
    voided: all.filter(t => t.voided).length,
    runner_errors: all.filter(t => !t.ok).length,
    grader_failed: all.filter(t => !t.grade_ok).length,
  }
}

// ---------------- Preflight ----------------
phase('Preflight')
log(`SPE ${R} eval. dryRun=${DRY}. cap=$${CAP_USD}. base trials per cell=${BASE_TRIALS}.`)

if (!budget.reserve(EST.preflight, 'preflight')) halt('The cap cannot cover the preflight.')
let pre = null
if (!state.halted) {
  pre = await agent([
    `You are the preflight checker for SPE round ${ROUND}. Run these from the repository root and report the results. Do not edit anything.`,
    `1. python spe/evals/graders/grade.py --selftest`,
    `   Set selftest_passed to true only if the oracle passes and the empty and wrong cases both fail. Copy the last 20 lines into selftest_output.`,
    `2. python spe/evals/harness/run_trial.py --list-tickets`,
    `   Set tickets to the IDs in printed order.`,
    `3. git log -1 --format='%h %s' -- spe/predictions/${R}.yaml`,
    `   Set predictions_commit to the output line.`,
    `4. git status --porcelain -- spe/predictions spe/plans spe/evals/graders spe/evals/tasks spe/evals/harness`,
    `   Set dirty_paths to one entry per output line. Use an empty list if there is no output.`,
  ].join('\n'), { label: 'preflight', phase: 'Preflight', schema: PREFLIGHT_SCHEMA, model: MODEL })
  budget.settle(EST.preflight, 0, EST.preflight)

  if (!pre.selftest_passed) halt(`Grader selftest failed: ${pre.selftest_output}`)
  else if (!pre.predictions_commit.includes(`SPE ${R} predict`)) halt(`The latest commit for spe/predictions/${R}.yaml is not the predict commit: "${pre.predictions_commit}"`)
  else if (pre.dirty_paths.length) halt(`Uncommitted edits under protected paths: ${pre.dirty_paths.join(', ')}`)
  else if (!DRY && pre.tickets.length !== EXPECTED_TICKETS) halt(`Expected ${EXPECTED_TICKETS} tickets, the runner listed ${pre.tickets.length}.`)
}

if (state.halted) {
  return { round: ROUND, dryRun: DRY, halted: true, haltReason: state.haltReason, preflight: pre, spend: { measured_usd: budget.measured, estimated_usd: budget.estimated, cap_usd: CAP_USD } }
}

// Cells interleave configs within each ticket, so a cap stop hits both configs evenly.
const tickets = DRY ? pre.tickets.slice(0, 2) : pre.tickets
let cells = []
for (const ticket of tickets) for (const config of CONFIGS) cells.push({ config, ticket })
if (DRY) cells = cells.slice(0, 3)
log(`${cells.length} cells across ${CONFIGS.join(', ')}. ${cells.length * BASE_TRIALS} base trials planned.`)

// Hold back money for analysis, critic, and writer so the close-out always fits.
const TAIL = EST.analysis + EST.critic + EST.writer
if (!budget.reserve(TAIL, 'analysis tail')) halt('The cap cannot cover analysis, critic, and writer.')

// ---------------- Trials ----------------
phase('Trials')
await parallel(cells.map(cell => () => runCell(cell, 0, BASE_TRIALS, 'Trials')))

// ---------------- Split cells ----------------
phase('Split cells')
const split = DRY ? [] : cells.filter(cell => {
  const s = (state.results.get(keyOf(cell)) || []).filter(t => t.base && scored(t))
  const p = s.filter(labelPass).length
  return s.length > 0 && p > 0 && p < s.length
})
log(`${split.length} split cells get up to ${EXTRA_TRIALS} extra trials each, capped at ${MAX_TRIALS_PER_CELL} per cell.`)
await parallel(split.map(cell => () => {
  const have = state.results.get(keyOf(cell)) || []
  const start = have.reduce((m, t) => Math.max(m, t.trial + 1), BASE_TRIALS)
  const n = Math.min(EXTRA_TRIALS, MAX_TRIALS_PER_CELL - start)
  return n > 0 ? runCell(cell, start, n, 'Split cells') : Promise.resolve([])
}))

// ---------------- Analysis ----------------
phase('Analysis')
let tailEstimated = 0
const metrics = {}
for (const config of CONFIGS) metrics[config] = metricsFor(config, cells.filter(c => c.config === config).length)

const failing = allTrials().filter(t => scored(t) && (!labelPass(t) || t.tone_pass === false))
let analysis = { failure_types: [], grader_bug_suspected: [] }
if (failing.length) {
  tailEstimated += EST.analysis
  const lines = failing.map(t =>
    `${t.config} ${t.ticket} t${t.trial} category=${t.category_correct} priority=${t.priority_correct} tone=${t.tone_pass} out=${t.output_path} transcript=${t.transcript_path}`)
  analysis = await agent([
    `You are the failure analyst for SPE round ${ROUND}. Do not edit any file.`,
    `Read spe/failures.md for the existing F-numbered failure types.`,
    `Then read the output and transcript files for the failing trials below. You may read spe/evals/tasks/answers.json to see expected labels.`,
    `Group the failures into types. Reuse an existing F-number when a type matches, and use id "new" otherwise.`,
    `For each type give name, kind, what, how to spot it, count per config, up to 5 example output paths, and a proposed fix.`,
    `List any failure that looks like a grader bug rather than a model failure in grader_bug_suspected.`,
    '',
    ...lines,
  ].join('\n'), { label: 'failure analysis', phase: 'Analysis', schema: ANALYSIS_SCHEMA, model: MODEL })
}

const missing = cells.filter(c => !(state.results.get(keyOf(c)) || []).length).map(keyOf)
const coverage = {
  round: ROUND,
  dry_run: DRY,
  expected_cells: cells.length,
  cells_with_results: cells.length - missing.length,
  cells_missing: missing,
  split_cells: split.map(keyOf),
  metrics,
  skips: budget.skips,
  cell_errors: state.cellErrors,
  grader_errors: state.graderErrors,
  voids: state.voids,
  halted: state.halted,
  halt_reason: state.haltReason,
}
tailEstimated += EST.critic
const critic = await agent([
  `You are the completeness critic for SPE round ${ROUND}. Do not edit any file.`,
  `Read spe/predictions/${R}.yaml and spe/plans/${R}.md. Then check the coverage report below against them.`,
  `List every gap that would make the predicted versus measured comparison unfair or incomplete. Examples are missing cells, low judge coverage, skipped trials that fall on one config, voids, and grader errors.`,
  `In unmeasured_predictions, list every predicted metric in the yaml that has no measured number below.`,
  `Set complete to true only if there are no gaps and no unmeasured predictions.`,
  '',
  JSON.stringify(coverage, null, 2),
].join('\n'), { label: 'completeness critic', phase: 'Analysis', schema: CRITIC_SCHEMA, model: MODEL })

// ---------------- Write results ----------------
phase('Write results')
const results = {
  ...coverage,
  failure_types: analysis.failure_types,
  grader_bug_suspected: analysis.grader_bug_suspected,
  critic,
  spend: {
    cap_usd: CAP_USD,
    measured_runner_usd: +budget.measured.toFixed(2),
    estimated_agent_usd: +(budget.estimated + tailEstimated + EST.writer).toFixed(2),
  },
  trials: allTrials().map(({ reply, ...rest }) => rest),
}
tailEstimated += EST.writer
const written = await agent([
  `Write the JSON below exactly to ${RESULTS_PATH}. Create the folder if it does not exist.`,
  `Then run: python -c "import json; json.load(open('${RESULTS_PATH}'))" to confirm that it parses.`,
  `Do not edit any other file. Do not commit.`,
  '',
  JSON.stringify(results, null, 2),
].join('\n'), { label: 'write results', phase: 'Write results', schema: WRITER_SCHEMA, model: MODEL })
budget.settle(TAIL, 0, tailEstimated)

const fmt = x => (x === null ? 'n/a' : x.toFixed(2))
const headline = CONFIGS.map(c => `${c} label ${fmt(metrics[c].label_acc)} tone ${fmt(metrics[c].tone_pass)}`).join(', ')
log(`Done. ${headline}. Spend: measured $${budget.measured.toFixed(2)}, estimated $${budget.estimated.toFixed(2)}, cap $${CAP_USD}. Skips: ${budget.skips.length}.`)

return {
  round: ROUND,
  dryRun: DRY,
  headline,
  halted: state.halted,
  haltReason: state.haltReason,
  metrics,
  splitCells: split.length,
  skips: budget.skips,
  voids: state.voids,
  graderErrors: state.graderErrors,
  cellErrors: state.cellErrors,
  failureTypes: analysis.failure_types,
  graderBugSuspected: analysis.grader_bug_suspected,
  critic,
  resultsPath: written.written ? written.path : null,
  spend: { measured_runner_usd: +budget.measured.toFixed(2), estimated_agent_usd: +budget.estimated.toFixed(2), cap_usd: CAP_USD },
}
```
